// Pedersen commitments: C = x·G + v·H
//   x = blinding factor (secret), v = amount.
// H is generated by hashing ("nothing up my sleeve"): nobody knows log_G(H), so nobody can
// open a commitment to two different amounts.
// Commitments are homomorphic: C(v1,x1) + C(v2,x2) = C(v1+v2, x1+x2),
// which allows proving that inputs = outputs + fee without revealing amounts.

import { FixedBase, hashToPoint, mulG, modN, INF, Point } from './secp256k1.js';
import * as core from './wasm.js';

// The Portuguese seed string below is part of CONSENSUS (it defines H, and every commitment
// depends on it): it must stay exactly as originally chosen. It means "Krevo value generator".
export const Hv = hashToPoint('pedersen/H', 'gerador de valor do Krevo');
const H_TABLE = new FixedBase(Hv);

// v·H in the constant-time core (amounts and masks are wallet secrets)
export function mulH(v) {
  if (!core.available()) return H_TABLE.mul(v);
  v = modN(v);
  if (v === 0n) return INF;
  const r = core.mulH(v);
  return Point.fromAffine(r[0], r[1]);
}
export const commit = (v, x) => mulG(x).add(mulH(v));
